const raw = $input.first().json.stdout.trim();
const result = JSON.parse(raw);

if (result.status !== 'ok') {
  throw new Error('Python script failed');
}

return [{
  json: {
    message: `Python ${result.python_version} is working on ${result.platform}`,
    timestamp: result.timestamp,
    details: result.stdlib_test
  }
}];
